CREATE COLUMN TABLE "TEST_AP"."ACRB" ("AbsEntry" INTEGER CS_INT NOT NULL , "CardCode" NVARCHAR(15) NOT NULL , "BankCode" NVARCHAR(30) NOT NULL , "Country" NVARCHAR(3) NOT NULL , "Account" NVARCHAR(50) NOT NULL , "Branch" NVARCHAR(50), "Street" NVARCHAR(100), "Block" NVARCHAR(100), "ZipCode" NVARCHAR(20), "City" NVARCHAR(100), "County" NVARCHAR(100), "State" NVARCHAR(3), "ControlKey" NVARCHAR(2), "UsrNumber1" NVARCHAR(25), "UsrNumber2" NVARCHAR(25), "UsrNumber3" NVARCHAR(25), "UsrNumber4" NVARCHAR(25), "IBAN" NVARCHAR(50), "LogInstanc" INTEGER CS_INT DEFAULT 0 NOT NULL , "Building" NCLOB MEMORY THRESHOLD 1000, "AliasName" NVARCHAR(50), "AcctType" NVARCHAR(1), "BankKey" INTEGER CS_INT, "BIK" NVARCHAR(15), "AcctName" NVARCHAR(250), "CorresAcct" NVARCHAR(30), "Phone" NVARCHAR(25), "Fax" NVARCHAR(25), "ISRType" SMALLINT CS_INT, "ISRBillerI" NVARCHAR(9), "CustIdNum" NVARCHAR(6) DEFAULT '0', "AddrType" NVARCHAR(100), "StreetNo" NVARCHAR(100), "SwiftNum" NVARCHAR(50), "ABARoutNum" NVARCHAR(25), "MandateID" NVARCHAR(35), "SignDate" LONGDATE CS_LONGDATE, "PWZAbsEntr" INTEGER CS_INT, "BranchChk" NVARCHAR(5), "MandatDate" LONGDATE CS_LONGDATE, "SeqType" NVARCHAR(4), "ActType" NVARCHAR(1), "IsPrenot" NVARCHAR(1) DEFAULT 'N', "EnAccount" NCLOB MEMORY THRESHOLD 1000, "EnIBAN" NCLOB MEMORY THRESHOLD 1000, "EncryptIV" NVARCHAR(100), PRIMARY KEY ("AbsEntry", "LogInstanc")) UNLOAD PRIORITY 5  AUTO MERGE ;
